export interface Schema {
  readonly kind: string;
  describe(): string;
}
/** Declares the type of the value it is given, like typebox's
 * `Type.Unsafe<T>`: the island hands back the caller's own type, so the
 * caller's declaration must describe what the island really returns. */
export declare function unsafe<T>(value: T): T;
/** A schema over the properties record it is given, like `Type.Object`. */
export declare function object<T>(properties: T): Schema & { readonly properties: T };
/** The sorted own keys of a value, joined. */
export declare function keys(value: unknown): string;
